  const [selectedIndustry, setSelectedIndustry] = useState<string | null>(null);

  const industries = [...new Set(blogPosts.map(post => post.industry))];
  const filteredPosts = selectedIndustry 
    ? blogPosts.filter(post => post.industry === selectedIndustry)
    : blogPosts;

  const handleShare = (platform: string, postTitle: string) => {
    // Simple mock sharing logic
    const url = window.location.href;
    const text = encodeURIComponent(`Check out this blog on SimpleAgentix: ${postTitle}`);
    let shareUrl = '';

    switch(platform) {
      case 'linkedin': shareUrl = `https://www.linkedin.com/sharing/share-offsite/?url=${url}`; break;
      case 'facebook': shareUrl = `https://www.facebook.com/sharer/sharer.php?u=${url}`; break;
      case 'whatsapp': shareUrl = `https://api.whatsapp.com/send?text=${text}%20${url}`; break;
    }
    window.open(shareUrl, '_blank');
  };

  const getTranslation = (post: BlogPost, field: 'title' | 'excerpt') => {
    return post[field][language] || post[field]['English'];
  };

  const sectionHeaders = {
